# shellcheck shell=bash
# State-changing operations. Every operation is idempotent: running it again
# with nothing to do changes nothing.
# SPDX-License-Identifier: MIT

# Paths are embedded in single quotes inside the wrapper; reject anything
# that could break out of them.
safe_path() { [[ $1 == /* && $1 != *"'"* && $1 != *$'\n'* && $1 != *'\'* ]]; }

render_wrapper() {
  local original=$1
  cat <<EOF
#!/usr/bin/env bash
$WRAPPER_MARKER
# Generated by $ILNF_NAME $(ilnf_version). Do not edit: run \`$ILNF_NAME repair\`.
# Starts Input Leap with the network filter preloaded into the GUI only.
ILNF_ORIGINAL='$original'
ILNF_LIB='$LIB_FILE'
ILNF_STATE_DIR='$STATE_DIR'

if [ ! -x "\$ILNF_ORIGINAL" ]; then
  echo "$ILNF_NAME: Input Leap executable not found: \$ILNF_ORIGINAL (run '$ILNF_NAME repair')" >&2
  exit 127
fi
# Recursion guard: never exec ourselves.
if [ "\$ILNF_ORIGINAL" -ef "\${BASH_SOURCE[0]}" ] ||
  { [ "\$(head -c 2 "\$ILNF_ORIGINAL")" = '#!' ] && grep -qF '$WRAPPER_MARKER' "\$ILNF_ORIGINAL"; }; then
  echo "$ILNF_NAME: wrapper points to itself, refusing to loop" >&2
  exit 126
fi

ilnf_use=1
[ -n "\${ILNF_DISABLE:-}" ] && ilnf_use=0
[ -e "\$ILNF_STATE_DIR/disabled" ] && ilnf_use=0
if [ "\$ilnf_use" = 1 ]; then
  # Only preload a regular file owned by us and not writable by others.
  if [ -f "\$ILNF_LIB" ] && [ ! -L "\$ILNF_LIB" ] && [ -O "\$ILNF_LIB" ]; then
    case "\$(stat -c %a "\$ILNF_LIB" 2>/dev/null)" in
      *[2367]? | *[2367]) ilnf_use=0 ;;
    esac
  else
    ilnf_use=0
  fi
fi
if [ "\$ilnf_use" = 1 ]; then
  case ":\${LD_PRELOAD:-}:" in
    *":\$ILNF_LIB:"*) ;; # already present, avoid loading twice
    *) export LD_PRELOAD="\$ILNF_LIB\${LD_PRELOAD:+:\$LD_PRELOAD}" ;;
  esac
fi
unset ilnf_use
# The library removes itself from LD_PRELOAD on load, so input-leaps and
# input-leapc started by the GUI do not inherit it.
exec "\$ILNF_ORIGINAL" "\$@"
EOF
}

wrapper_original() { sed -n "s/^ILNF_ORIGINAL='\(.*\)'$/\1/p" "$1" | head -n1; }

install_app_files() {
  [[ $(realpath -- "$ILNF_ROOT") == "$(realpath -m -- "$APP_DIR")" ]] && return 0
  local stage
  if [[ $OPT_DRY_RUN == 1 ]]; then
    info "$(t dry_run): copy CLI to $APP_DIR"
    return 0
  fi
  mkdir -p -- "$DATA_DIR"
  local -a items=(bin scripts locales config src include tools VERSION CMakeLists.txt tests/fixtures/fake_input_leap.cpp)
  local same=1 i
  for i in "${items[@]}"; do
    diff -rq -- "$ILNF_ROOT/$i" "$APP_DIR/$i" >/dev/null 2>&1 || { same=0; break; }
  done
  [[ $same == 1 ]] && return 0
  stage=$(mktemp -d -- "$DATA_DIR/.app.XXXXXX")
  cp -R -- "$ILNF_ROOT/bin" "$ILNF_ROOT/scripts" "$ILNF_ROOT/locales" "$ILNF_ROOT/config" \
    "$ILNF_ROOT/src" "$ILNF_ROOT/include" "$ILNF_ROOT/tools" "$ILNF_ROOT/VERSION" \
    "$ILNF_ROOT/CMakeLists.txt" "$stage/"
  mkdir -p -- "$stage/tests/fixtures" "$stage/tests/unit" "$stage/tests/bench" "$stage/tests/integration"
  cp -- "$ILNF_ROOT/tests/fixtures/fake_input_leap.cpp" "$stage/tests/fixtures/"
  chmod -R go-w -- "$stage"
  # Swap directories (old copy kept until the new one is in place).
  if [[ -d $APP_DIR ]]; then
    mv -T -- "$APP_DIR" "$APP_DIR.old.$$"
    mv -T -- "$stage" "$APP_DIR"
    rm -rf -- "$APP_DIR.old.$$"
  else
    mv -T -- "$stage" "$APP_DIR"
  fi
}

install_cli_link() {
  local want="$APP_DIR/bin/$ILNF_NAME"
  if [[ -L $CLI_LINK && $(readlink -- "$CLI_LINK") == "$want" ]]; then return 0; fi
  if [[ -e $CLI_LINK || -L $CLI_LINK ]]; then
    warn "$(t warn_cli_exists "$CLI_LINK")"
    return 0
  fi
  run mkdir -p -- "$USER_BIN"
  run ln -s -- "$want" "$CLI_LINK"
}

ensure_config() {
  [[ -f $CONFIG_FILE ]] && return 0
  run mkdir -p -- "$CONFIG_DIR"
  atomic_write "$CONFIG_FILE" 600 <"$ILNF_ROOT/config/config.toml"
  info "$(t cfg_created "$CONFIG_FILE")"
}

# install_library BUILD_DIR -> sets LIB_CHANGED=1 if a new library was activated.
install_library() {
  local b=$1 new old
  LIB_CHANGED=0
  new=$(sha256 "$b/network-filter.so")
  old=$(sha256 "$LIB_FILE")
  run mkdir -p -- "$LIB_DIR"
  [[ $OPT_DRY_RUN == 1 ]] || chmod 755 -- "$LIB_DIR"
  if [[ $new != "$old" ]]; then
    if [[ -f $LIB_FILE ]]; then
      atomic_copy "$LIB_FILE" "$LIB_FILE.prev" 644
      MF[prev_lib_sha256]=$old
    fi
    atomic_copy "$b/network-filter.so" "$LIB_FILE" 644
    LIB_CHANGED=1
  fi
  local f
  for f in ilnf-probe fake-input-leap; do
    if ! cmp -s -- "$b/$f" "$LIB_DIR/$f" 2>/dev/null; then atomic_copy "$b/$f" "$LIB_DIR/$f" 755; fi
  done
  MF[lib_sha256]=$new
}

# Rewrite Exec/TryExec of a desktop entry to point at WRAPPER.
render_desktop_override() {
  local src=$1 wrapper=$2
  awk -v w="$wrapper" -v marker="$DESKTOP_MARKER" '
    BEGIN { done = 0 }
    /^\[Desktop Entry\]/ { print; if (!done) { print marker; done = 1 }; next }
    /^X-ILNF-Managed=/ { next }
    /^Exec=/ { sub(/^Exec=[^ ]*/, "Exec=" w); print; next }
    /^TryExec=/ { print "TryExec=" w; next }
    { print }
  ' "$src"
}

install_desktop_overrides() {
  local wrapper=$1 f base dest i=0 list=""
  while IFS= read -r f; do
    base=$(basename -- "$f")
    case $f in
      "$AUTOSTART_DIR"/* | /etc/xdg/autostart/*) dest="$AUTOSTART_DIR/$base" ;;
      *) dest="$APPS_DIR/$base" ;;
    esac
    # Entries already pointing at the wrapper are fine.
    if [[ -f $dest ]] && grep -qxF "$DESKTOP_MARKER" "$dest"; then
      render_desktop_override "$f" "$wrapper" | write_if_changed "$dest" 644 || true
    else
      if [[ -f $dest && $dest == "$f" ]]; then
        # A user-owned entry: back it up before taking it over.
        run mkdir -p -- "$BACKUP_DIR/desktop"
        [[ -f $BACKUP_DIR/desktop/$base ]] || run cp -p -- "$dest" "$BACKUP_DIR/desktop/$base"
      elif [[ -f $dest ]]; then
        continue # a different user file with the same id: leave it alone
      fi
      render_desktop_override "$f" "$wrapper" | atomic_write "$dest" 644
    fi
    list+="${list:+;}$dest"
    i=$((i + 1))
  done < <(find_desktop_entries | awk '!seen[$0]++' | sort -u)
  MF[desktop_files]=$list
  verbose "$(t desktop_count "$i")"
}

# ------------------------------------------------------------------ install
do_install() {
  local label=${1:-install}
  acquire_lock
  detect_os
  detect_pkg_manager
  detect_input_leap

  [[ -f $JOURNAL ]] && warn "$(t warn_interrupted "$(cat "$JOURNAL")")"

  case $IL_STATE in
    missing) die "$EX_NOT_INSTALLED" "$(t err_il_missing)" ;;
    unsupported) die "$EX_UNSUPPORTED" "$(t err_il_unsupported "${IL_METHOD:-?}" "$IL_REASON")" ;;
  esac
  local level
  level=$(support_level)
  info "$(t inst_env "$OS_NAME" "$ARCH" "$level")"
  info "$(t inst_found "$IL_REAL" "${IL_VERSION:-?}" "$IL_QT" "$IL_METHOD")"
  [[ $level == Unsupported ]] && warn "$(t warn_unsupported_os)"
  [[ -n $IL_RUNPATH ]] && warn "$(t warn_runpath "$IL_RUNPATH")"
  safe_path "$IL_LAUNCH" && safe_path "$IL_REAL" && safe_path "$LIB_FILE" ||
    die "$EX_UNSUPPORTED" "$(t err_unsafe_path)"

  local mode
  mode=$(choose_mode)
  info "$(t inst_mode "$mode")"
  local running
  running=$(running_input_leap)
  [[ -n $running ]] && warn "$(t warn_running)"

  # Build (or reuse) the library for the Qt major used by Input Leap.
  local bdir
  bdir=$(mktemp -d)
  # shellcheck disable=SC2064
  trap "rm -rf -- '$bdir'" EXIT
  local need_build=1
  if [[ -f $LIB_FILE && ${MF[qt_major]:-} == "$IL_QT" && $(sha256 "$LIB_FILE") == "${MF[lib_sha256]:-x}" &&
    ${MF[version]:-} == "$(ilnf_version)" && -x $LIB_DIR/fake-input-leap && -x $PROBE ]]; then
    need_build=0
    verbose "$(t lib_up_to_date)"
  fi
  if [[ $need_build == 1 ]]; then
    if [[ $OPT_DRY_RUN == 1 ]]; then
      info "$(t dry_run): build filter for Qt$IL_QT"
    else
      ensure_build_deps "$IL_QT"
      info "$(t building "$IL_QT")"
      build_all "$IL_QT" "$bdir"
      validate_library "$bdir/network-filter.so" "$bdir/fake-input-leap" "$IL_QT" ||
        die "$EX_BUILD" "$(t err_validation)"
      ok_line "$(t lib_validated)"
      install_library "$bdir"
    fi
  fi

  local mf_before
  mf_before=$(manifest_snapshot)
  # From here on the system is modified: record the transaction.
  journal_begin "$label"
  install_app_files
  install_cli_link
  ensure_config

  # ---- wrapper
  local target=$IL_LAUNCH original wrapper_path wrapper_new
  if [[ $mode == inplace ]]; then
    original="$target.original"
    wrapper_path=$target
    if is_our_wrapper "$target"; then
      original=$(wrapper_original "$target")
    elif is_legacy_wrapper "$target"; then
      is_elf "$original" || die "$EX_CONFLICT" "$(t err_legacy_broken "$original")"
      info "$(t migrating_legacy)"
      run mkdir -p -- "$BACKUP_DIR"
      [[ -f $BACKUP_DIR/legacy-wrapper ]] || run cp -p -- "$target" "$BACKUP_DIR/legacy-wrapper"
      MF[legacy_migrated]=1
    elif is_elf "$target"; then
      if [[ -e $original ]]; then
        # Input Leap was updated by overwriting the wrapper with a new binary.
        if [[ -n ${MF[original]:-} && $original == "${MF[original]}" ]]; then
          warn "$(t warn_external_update "$target")"
          confirm "$(t ask_adopt_update)" || die "$EX_CONFLICT" "$(t err_adopt_declined)"
          run mv -fT -- "$target" "$original"
        else
          die "$EX_CONFLICT" "$(t err_original_exists "$original")"
        fi
      else
        assert_not_symlink "$target"
        run mv -T -- "$target" "$original" # atomic rename in the same directory
      fi
    else
      die "$EX_CONFLICT" "$(t err_unknown_target "$target")"
    fi
  else
    original=$IL_REAL
    wrapper_path="$LIB_DIR/input-leap"
  fi

  wrapper_new=$(render_wrapper "$original")
  if [[ $OPT_DRY_RUN == 1 ]]; then
    info "$(t dry_run): write wrapper $wrapper_path"
  elif printf '%s\n' "$wrapper_new" | write_if_changed "$wrapper_path" 755; then
    verbose "$(t wrapper_written "$wrapper_path")"
  fi

  if [[ $mode == external ]]; then
    # Convenience shim on PATH, only if the name is free or already ours.
    local shim="$USER_BIN/input-leap"
    if [[ ! -e $shim ]] || is_our_wrapper "$shim"; then
      [[ $OPT_DRY_RUN == 1 ]] || printf '%s\n' "$wrapper_new" | write_if_changed "$shim" 755 || true
      MF[shim]=$shim
    fi
    install_desktop_overrides "$wrapper_path"
  fi

  if [[ $OPT_DRY_RUN == 0 ]]; then
    MF[version]=$(ilnf_version)
    MF[mode]=$mode
    MF[target]=$target
    MF[original]=$original
    MF[original_sha256]=$(sha256 "$original")
    MF[wrapper]=$wrapper_path
    MF[wrapper_sha256]=$(sha256 "$wrapper_path")
    MF[qt_major]=$IL_QT
    MF[qt_system_version]=$(qt_version_of_system "$IL_QT")
    MF[input_leap_version]=$IL_VERSION
    MF[installed_at]=${MF[installed_at]:-$(date -u +%FT%TZ)}
    MF[os]="$OS_ID $OS_VERSION"
    # Only rewrite the manifest when something actually changed.
    if [[ $(manifest_snapshot) != "$mf_before" ]]; then
      MF[updated_at]=$(date -u +%FT%TZ)
      manifest_save
    fi
  fi
  journal_end

  ok_line "$(t inst_done)"
  [[ -f $DISABLED_FLAG ]] && warn "$(t warn_still_disabled)"
  [[ -n $running ]] && info "$(t hint_restart)"
  [[ $mode == external ]] && info "$(t hint_external "$wrapper_path")"
  if [[ -f $LEGACY_LIB && ${MF[legacy_migrated]:-0} == 1 ]]; then info "$(t hint_legacy_lib "$(dirname -- "$LEGACY_LIB")")"; fi
  return 0
}

# ---------------------------------------------------------------- uninstall
do_uninstall() {
  acquire_lock
  if ! manifest_load; then
    if [[ $OPT_PURGE == 1 ]]; then
      purge_files
      return 0
    fi
    die "$EX_NOT_INSTALLED" "$(t err_not_installed)"
  fi
  local mode=${MF[mode]} target=${MF[target]} original=${MF[original]} wrapper=${MF[wrapper]}
  journal_begin uninstall

  if [[ $mode == inplace ]]; then
    if [[ -e $target ]] && ! is_our_wrapper "$target"; then
      die "$EX_CONFLICT" "$(t err_target_not_ours "$target")"
    fi
    if [[ -f $original ]]; then
      [[ $(sha256 "$original") == "${MF[original_sha256]}" ]] || warn "$(t warn_original_changed "$original")"
      run mv -fT -- "$original" "$target"
      ok_line "$(t restored "$target")"
    else
      warn "$(t warn_original_missing "$original")"
    fi
  else
    is_our_wrapper "$wrapper" && run rm -f -- "$wrapper"
    if [[ -n ${MF[shim]:-} ]] && is_our_wrapper "${MF[shim]}"; then run rm -f -- "${MF[shim]}"; fi
  fi

  # Desktop overrides: remove ours, restore user files we backed up.
  local f base IFS=';'
  for f in ${MF[desktop_files]:-}; do
    [[ -f $f ]] && grep -qxF "$DESKTOP_MARKER" "$f" || continue
    base=$(basename -- "$f")
    if [[ -f $BACKUP_DIR/desktop/$base ]]; then
      run mv -fT -- "$BACKUP_DIR/desktop/$base" "$f"
    else
      run rm -f -- "$f"
    fi
  done
  unset IFS

  if [[ -L $CLI_LINK && $(readlink -- "$CLI_LINK") == "$APP_DIR/"* ]]; then run rm -f -- "$CLI_LINK"; fi
  run rm -rf -- "$LIB_DIR" "$APP_DIR"
  run rm -f -- "$MANIFEST" "$DISABLED_FLAG"
  journal_end
  [[ $OPT_PURGE == 1 ]] && purge_files

  # Verify restoration.
  if [[ $mode == inplace && $OPT_DRY_RUN == 0 ]]; then
    if is_elf "$target"; then ok_line "$(t verify_restored)"; else warn "$(t warn_verify_failed "$target")"; fi
  fi
  if [[ ${MF[legacy_migrated]:-0} == 1 && $OPT_PURGE == 0 ]]; then info "$(t hint_legacy_backup "$BACKUP_DIR/legacy-wrapper")"; fi
  ok_line "$(t uninst_done)"
}

purge_files() {
  # Only directories that belong exclusively to this project.
  local d
  for d in "$CONFIG_DIR" "$DATA_DIR" "$STATE_DIR"; do
    [[ $d == */$ILNF_NAME ]] || continue
    [[ -e $d ]] && run rm -rf -- "$d"
  done
  ok_line "$(t purged)"
}

# ---------------------------------------------------------------- enable/disable
do_enable() {
  is_installed || die "$EX_NOT_INSTALLED" "$(t err_not_installed)"
  if [[ -e $DISABLED_FLAG ]]; then run rm -f -- "$DISABLED_FLAG"; fi
  ok_line "$(t enabled)"
  info "$(t hint_restart)"
}

do_disable() {
  is_installed || die "$EX_NOT_INSTALLED" "$(t err_not_installed)"
  if [[ ! -e $DISABLED_FLAG ]]; then
    run mkdir -p -- "$STATE_DIR"
    run touch -- "$DISABLED_FLAG"
  fi
  ok_line "$(t disabled)"
  info "$(t hint_restart)"
}

# ---------------------------------------------------------------- rollback
do_rollback() {
  acquire_lock
  manifest_load || die "$EX_NOT_INSTALLED" "$(t err_not_installed)"
  local prev="$LIB_FILE.prev"
  [[ -f $prev ]] || die "$EX_ERROR" "$(t err_no_rollback)"
  [[ $(sha256 "$prev") == "${MF[prev_lib_sha256]:-}" ]] || die "$EX_CONFLICT" "$(t err_rollback_integrity)"
  validate_library "$prev" "$LIB_DIR/fake-input-leap" "${MF[qt_major]}" || die "$EX_BUILD" "$(t err_validation)"
  local cur tmp
  cur=$(sha256 "$LIB_FILE")
  tmp=$(mktemp -- "$LIB_DIR/.swap.XXXXXX")
  run cp -p -- "$LIB_FILE" "$tmp"
  atomic_copy "$prev" "$LIB_FILE" 644
  run mv -fT -- "$tmp" "$prev"
  MF[lib_sha256]=${MF[prev_lib_sha256]}
  MF[prev_lib_sha256]=$cur
  [[ $OPT_DRY_RUN == 1 ]] || manifest_save
  ok_line "$(t rolled_back)"
}

# ---------------------------------------------------------------- repair
do_repair() {
  manifest_load || true
  if ! is_installed && [[ ! -f $JOURNAL ]]; then
    die "$EX_NOT_INSTALLED" "$(t err_not_installed)"
  fi
  # Re-running the idempotent installer fixes every state it can prove safe:
  # missing/modified library, missing wrapper, external Input Leap updates,
  # missing desktop overrides and interrupted transactions.
  do_install repair
}

# ---------------------------------------------------------------- configure
# Regenerate config.toml from structured values.
render_config() {
  local enabled=$1 mode=$2 profiles=$3 exclude=$4 include=$5 logging=$6 level=$7
  local arr
  arr() {
    local IFS=$'\n' out="" x
    for x in $1; do [[ -n $x ]] && out+="${out:+, }\"$x\""; done
    printf '[%s]' "$out"
  }
  cat <<EOF
# Input Leap Network Filter configuration (written by \`$ILNF_NAME configure\`)
# See $ILNF_NAME help and docs/configuration.md. Parsed as data, never executed.

[filter]
enabled = $enabled
mode = "$mode"

[interfaces]
profiles = $(arr "$profiles")
exclude = $(arr "$exclude")
include = $(arr "$include")

[logging]
enabled = $logging
level = "$level"
EOF
}

# do_configure [--add-exclude P] [--remove-exclude P] [--add-include P]
#              [--remove-include P] [--profiles a,b] [--mode M] [--show] [--edit]
do_configure() {
  local probe
  probe=$(get_probe) || die "$EX_DEPS" "$(t err_no_probe)"
  ensure_config
  if [[ $# -eq 0 ]]; then
    if is_interactive; then
      configure_interactive "$probe"
      return
    fi
    set -- --show
  fi

  local dump enabled mode logging level profiles="" exclude="" include="" k v
  dump=$("$probe" dump --config "$CONFIG_FILE") || die "$EX_ERROR" "$(t err_config_invalid "$CONFIG_FILE")"
  while IFS=$'\t' read -r k v; do
    case $k in
      enabled) enabled=$v ;; mode) mode=$v ;; logging) logging=$v ;; level) level=$v ;;
      profile) profiles+="$v"$'\n' ;; exclude) exclude+="$v"$'\n' ;; include) include+="$v"$'\n' ;;
    esac
  done <<<"$dump"

  local changed=0
  _list_add() { if grep -qxF -- "$2" <<<"$1"; then printf '%s' "$1"; else printf '%s\n%s' "$1" "$2"; fi; }
  _list_del() { grep -vxF -- "$2" <<<"$1" || true; }
  while [[ $# -gt 0 ]]; do
    case $1 in
      --show) cat -- "$CONFIG_FILE"; return 0 ;;
      --edit)
        is_interactive || die "$EX_USAGE" "$(t err_needs_tty)"
        "${VISUAL:-${EDITOR:-vi}}" "$CONFIG_FILE"
        "$probe" check-config --config "$CONFIG_FILE" || warn "$(t warn_config_invalid_passthrough)"
        return 0
        ;;
      --add-exclude) exclude=$(_list_add "$exclude" "${2:?}"); shift ;;
      --remove-exclude) exclude=$(_list_del "$exclude" "${2:?}"); shift ;;
      --add-include) include=$(_list_add "$include" "${2:?}"); shift ;;
      --remove-include) include=$(_list_del "$include" "${2:?}"); shift ;;
      --profiles) profiles=$(tr ',' '\n' <<<"${2?}"); shift ;;
      --mode) mode=${2:?}; shift ;;
      --enable-logging) logging=true ;;
      --disable-logging) logging=false ;;
      *) die "$EX_USAGE" "$(t err_unknown_option "$1")" ;;
    esac
    changed=1
    shift
  done
  [[ $changed == 1 ]] || return 0
  save_config "$probe" "$enabled" "$mode" "$profiles" "$exclude" "$include" "$logging" "$level"
}

save_config() {
  local probe=$1 tmp
  shift
  tmp=$(mktemp)
  render_config "$@" >"$tmp"
  # Validate with the same parser the library uses before replacing anything.
  if ! "$probe" check-config --config "$tmp" >/dev/null; then
    "$probe" check-config --config "$tmp" >&2 || true
    rm -f -- "$tmp"
    die "$EX_USAGE" "$(t err_config_rejected)"
  fi
  if write_if_changed "$CONFIG_FILE" 600 <"$tmp"; then ok_line "$(t cfg_saved "$CONFIG_FILE")"; else info "$(t cfg_unchanged)"; fi
  rm -f -- "$tmp"
}

configure_interactive() {
  local probe=$1 choice pat
  while true; do
    echo
    sed -n '/^\[/,$p' -- "$CONFIG_FILE" | grep -v '^#'
    echo
    t cfg_menu
    echo
    read -r -p "> " choice || return 0
    case $choice in
      1) read -r -p "$(t ask_pattern) " pat && do_configure --add-exclude "$pat" ;;
      2) read -r -p "$(t ask_pattern) " pat && do_configure --remove-exclude "$pat" ;;
      3) read -r -p "$(t ask_pattern) " pat && do_configure --add-include "$pat" ;;
      4) read -r -p "$(t ask_pattern) " pat && do_configure --remove-include "$pat" ;;
      5) "$probe" profiles; read -r -p "$(t ask_profiles) " pat && do_configure --profiles "$pat" ;;
      6) do_preview ;;
      0 | "") return 0 ;;
    esac
  done
}

do_reset() {
  [[ -f $CONFIG_FILE ]] || {
    ensure_config
    return 0
  }
  confirm "$(t ask_reset "$CONFIG_FILE")" || die "$EX_ERROR" "$(t cancelled)"
  run mkdir -p -- "$BACKUP_DIR"
  run cp -p -- "$CONFIG_FILE" "$BACKUP_DIR/config.toml.$(date +%Y%m%d%H%M%S)"
  if write_if_changed "$CONFIG_FILE" 600 <"$ILNF_ROOT/config/config.toml"; then ok_line "$(t cfg_reset)"; else info "$(t cfg_unchanged)"; fi
}
